import Extend from 'flarum/common/extenders';
import Discussion from 'flarum/common/models/Discussion';
import Media from './models';
export default [new Extend.Store().add('marquee-media', Media), new Extend.Model(Discussion).hasOne('marqueeMedia').hasMany('marqueeRelatedMedia').attribute('marqueeSeason').attribute('marqueeEpisode').attribute('marqueeSeasonData')];