import Component from 'flarum/common/Component';
import ItemList from 'flarum/common/utils/ItemList';
import listItems from 'flarum/common/helpers/listItems';
import classList from 'flarum/common/utils/classList';
import tagsLabel from 'ext:flarum/tags/common/helpers/tagsLabel';
import app from 'flarum/forum/app';
import { t, text, img, sourceName, pickFromMedia, titleFor, titleYear, showSourceLink, backdropColor, backdropTagColor, hexColor } from '../util';
import { loadSeason, primeSeason } from '../api';
import { startDiscussion } from '../utils/startDiscussion';
import Button from 'flarum/common/components/Button';
import isDark from 'flarum/common/utils/isDark';
import { loadedSeasonBrowser, openEpisodeModal, openLinkModal } from './openers';
import { subject } from '../subjects';
/**
 * Replaces the discussion hero when the discussion is linked to a movie, show
 * (or one season or episode of it) or game. Keeps the core title and badge
 * classes so themes still apply.
 */
export default class MediaHero extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    const {
      media,
      season,
      seasonData
    } = this.attrs.link;
    primeSeason(media.id(), seasonData);
    this.seasonData = seasonData;
    if (season && !seasonData) {
      loadSeason(media.id(), season).then(data => {
        this.seasonData = data;
        m.redraw();
      },
      // The card keeps to what the show's details say about the season (an episode's own aren't known).
      () => {});
    }
  }

  /**
   * The buttons under the card. Other extensions add to it: each gets the
   * discussion, the linked media and what this card is about (season, episode).
   */
  actionItems() {
    const {
      media,
      season
    } = this.attrs.link;
    const d = this.details();
    const s = subject(...this.subjectArgs());
    const pick = pickFromMedia(media);
    const ep = this.episode();
    const source = sourceName(media.kind());
    const items = new ItemList();

    // The admin can hide the button; the attribution below always stays (TMDB and IGDB ask for it).
    if (showSourceLink()) {
      items.add('source', m("a", {
        className: "Button Button--primary",
        href: s.url,
        target: "_blank",
        rel: "noopener noreferrer"
      }, s.linkLabel || t('hero.view_on', {
        source
      })), 100);
    }
    this.addWatchItem(items, d, pick, ep);
    if (season && app.session.user) {
      items.add('discussShow', m("button", {
        type: "button",
        className: "Button",
        onclick: () => startDiscussion(pick)
      }, m("i", {
        className: "fas fa-tv",
        "aria-hidden": "true"
      }), " ", t('hero.discuss_show')), 80);
    }
    items.add('attribution', this.attribution(d, source), -100);
    return items;
  }

  /** For an episode, its details; otherwise the trailer, if there is one. */
  addWatchItem(items, d, pick, ep) {
    if (ep) {
      items.add('episode', m("button", {
        type: "button",
        className: "Button",
        onclick: () => openEpisodeModal(pick, this.seasonData, ep)
      }, m("i", {
        className: "fas fa-info-circle",
        "aria-hidden": "true"
      }), " ", t('hero.episode_details')), 90);
    } else if (d.trailer) {
      items.add('trailer', m("a", {
        className: "Button",
        href: `https://www.youtube.com/watch?v=${d.trailer}`,
        target: "_blank",
        rel: "noopener noreferrer"
      }, m("i", {
        className: "fas fa-play",
        "aria-hidden": "true"
      }), " ", t('hero.trailer')), 90);
    }
  }

  /** Where the data comes from, as the sources ask, and who wrote or translated the description. */
  attribution(d, source) {
    return m("span", {
      className: "MarqueeHero-attribution"
    }, t(`hero.attribution_${source.toLowerCase().replace(' ', '_')}`), d.wikipedia?.url ? [' · ', t('hero.from_wikipedia', {
      a: m("a", {
        href: d.wikipedia.url,
        target: "_blank",
        rel: "noopener noreferrer"
      }),
      license: m("a", {
        href: "https://creativecommons.org/licenses/by-sa/4.0/",
        target: "_blank",
        rel: "noopener noreferrer license"
      })
    })] : null, d.translation?.by === 'deepl' ? [' · ', t('hero.translated_deepl')] : null);
  }

  /**
   * No description in the data language (no Wikipedia article, no DeepL): say
   * so, and keep the source's English behind a toggle, as Curio does.
   */
  untranslated(s) {
    const untranslated = s.untranslated;
    const names = new Intl.DisplayNames([app.translator.getLocale() || 'en'], {
      type: 'language'
    });
    const name = code => {
      try {
        return names.of(code);
      } catch (e) {
        // Not a language code Intl knows: show the code itself.
        return code;
      }
    };
    const other = name(untranslated.have);
    return m("div", {
      className: "MarqueeHero-overview MarqueeHero-overview--missing"
    }, m("p", null, t('hero.no_description', {
      language: name(untranslated.want.split('-')[0])
    })), m("button", {
      type: "button",
      className: "Button Button--link",
      "aria-expanded": String(!!this.showOther),
      onclick: () => this.showOther = !this.showOther
    }, t(this.showOther ? 'hero.hide_other' : 'hero.show_other', {
      language: other
    })), this.showOther ? m("p", {
      lang: untranslated.have
    }, s.overview) : null);
  }

  /** The discussion's titles (linked one first): picking one shows its card here. */
  series(series, shown) {
    return m("ul", {
      className: "MarqueeHero-series",
      "aria-label": text('hero.series')
    }, series.map(work => m("li", null, m("button", {
      type: "button",
      className: "MarqueeHero-seriesItem",
      "aria-pressed": String(work === shown),
      onclick: () => {
        if (work !== shown) this.attrs.onswitch?.(work);
      }
    }, work.title(), work.year() ? m("small", null, work.year()) : null))));
  }

  /** The card is only drawn once the discussion page has loaded the details (see forum/index). */
  details() {
    return this.attrs.link.media.details();
  }
  episode() {
    const {
      episode
    } = this.attrs.link;
    return episode && this.seasonData?.episodes.find(e => e.n === episode) || null;
  }
  subjectArgs() {
    const {
      media,
      season,
      episode
    } = this.attrs.link;
    return [media, this.details(), season, episode, this.seasonData];
  }

  /**
   * The card is titled by the work itself. A discussion renamed to something
   * else ("This indie game is one of my favourites") keeps that as a headline
   * above it. Until an episode's data arrives its title isn't known yet.
   */
  workTitle() {
    const {
      media,
      season,
      episode
    } = this.attrs.link;
    const ep = this.episode();
    // Titles made before the year was switched off still carry it: not a rename.
    return episode && !ep ? this.attrs.discussion.title() : titleFor(pickFromMedia(media), season, ep);
  }
  renamed(workTitle) {
    const {
      media,
      season
    } = this.attrs.link;
    const title = this.attrs.discussion.title();
    // A related title picked from the row is checked against the linked one:
    // the discussion is named after that, not renamed (Wlork, Discuss d/40077 #85).
    const main = this.attrs.main;
    return main && main.media !== media ? !main.episode && ![false, true].some(year => titleFor(pickFromMedia(main.media), main.season, null, year) === title) : workTitle !== title && titleFor(pickFromMedia(media), season, this.episode(), true) !== title;
  }

  /** Each title on the card may have its own background (uploaded, or none). */
  backdrop(s) {
    const own = (this.attrs.discussion.attribute('marqueeBackdrops') || {})[String(this.attrs.link.media.id())];
    return own === 'none' ? null : own || s.backdrop;
  }

  /**
   * Without an image: the admin's colour, the tag's if chosen (as Flarum's own
   * header), or the forum's banner colour (as the welcome banner).
   */
  color(backdrop, tags) {
    if (backdrop) return null;
    return backdropColor() || backdropTagColor() && tags.map(tag => tag.color()).find(Boolean) || hexColor(getComputedStyle(document.body).getPropertyValue('--hero-bg').trim());
  }
  tags() {
    const tags = this.attrs.discussion.tags && this.attrs.discussion.tags();
    return (tags || []).filter(tag => !!tag);
  }
  view() {
    const {
      discussion,
      link
    } = this.attrs;
    const media = link.media;
    const s = subject(...this.subjectArgs());
    const workTitle = this.workTitle();
    const renamed = this.renamed(workTitle);
    const backdrop = this.backdrop(s);
    const color = this.color(backdrop, this.tags());
    return m("header", {
      className: classList('Hero DiscussionHero MarqueeHero', `MarqueeHero--${media.kind()}`, {
        'MarqueeHero--episode': this.episode(),
        'MarqueeHero--renamed': renamed,
        'MarqueeHero--backdrop': !!backdrop,
        'MarqueeHero--color': !!color,
        'MarqueeHero--light': !!color && !isDark(color)
      }),
      style: color ? {
        '--marquee-bg': color
      } : undefined
    }, backdrop ? m("div", {
      className: "MarqueeHero-backdrop",
      style: {
        backgroundImage: `url(${backdrop})`
      }
    }) : null, discussion.attribute('canMarqueeLink') ? m(Button, {
      className: "Button Button--icon MarqueeHero-edit",
      icon: "fas fa-pen",
      "aria-label": text('link.edit_card'),
      title: text('link.edit_card'),
      onclick: () => openLinkModal(discussion, media)
    }) : null, m("div", {
      className: "container MarqueeHero-inner"
    }, s.poster ? m("img", {
      className: "MarqueeHero-poster",
      src: img(s.poster, 'w342'),
      alt: "",
      fetchpriority: "high"
    }) : m("span", {
      className: "MarqueeHero-poster"
    }), m("div", {
      className: "MarqueeHero-body"
    }, this.body(s, workTitle, renamed))));
  }

  /** Everything beside the poster, top to bottom. */
  body(s, workTitle, renamed) {
    const {
      link,
      series
    } = this.attrs;
    const pick = pickFromMedia(link.media);
    const title = this.attrs.discussion.title();
    return [this.heroItems(), renamed ? m("h1", {
      className: "MarqueeHero-headline"
    }, title) : null, renamed ? m("h2", {
      className: "DiscussionHero-title"
    }, workTitle) : m("h1", {
      className: "DiscussionHero-title"
    }, workTitle), m("ul", {
      className: "MarqueeHero-meta"
    }, s.meta.filter(Boolean).map(part => m("li", null, part))), series ? this.series(series, link.media) : null, m("div", {
      className: "MarqueeHero-scores"
    }, s.score), this.credits(s), this.overview(s), s.extra || null, this.people(s), pick.seasons && pick.seasons.length ? this.seasonBrowser(pick) : null, m("div", {
      className: "MarqueeHero-links"
    }, this.actionItems().toArray())];
  }

  /** Core's tags and badges, and for a season or episode the show it belongs to. */
  heroItems() {
    const {
      discussion,
      link
    } = this.attrs;
    const {
      media,
      season
    } = link;
    const badges = discussion.badges().toArray();
    const tags = discussion.tags && discussion.tags();
    return m("ul", {
      className: "DiscussionHero-items"
    }, tags && tags.length ? m("li", {
      className: "item-tags"
    }, tagsLabel(tags, {
      link: true
    })) : null, badges.length ? m("li", {
      className: "item-badges"
    }, m("ul", {
      className: "DiscussionHero-badges badges"
    }, listItems(badges))) : null, season ? m("li", {
      className: "MarqueeHero-parent"
    }, m("i", {
      className: "fas fa-tv",
      "aria-hidden": "true"
    }), " ", media.year() && titleYear() ? `${media.title()} (${media.year()})` : media.title()) : null);
  }
  credits(s) {
    if (!s.credits.length) return null;
    return m("dl", {
      className: "MarqueeHero-credits"
    }, s.credits.map(([k, v]) => m("div", null, m("dt", null, k), m("dd", null, v))));
  }
  overview(s) {
    if (s.overview && s.untranslated) return this.untranslated(s);
    return s.overview ? m("p", {
      className: "MarqueeHero-overview"
    }, s.overview) : null;
  }
  people(s) {
    if (!s.people || !s.people[1] || !s.people[1].length) return null;
    const [heading, people] = s.people;
    return m("div", null, m("h2", {
      className: "MarqueeHero-sectionTitle"
    }, heading), m("ul", {
      className: "MarqueeHero-cast"
    }, people.map(c => m("li", null, c.photo ? m("img", {
      src: img(c.photo, 'w185'),
      alt: "",
      loading: "lazy",
      decoding: "async"
    }) : m("span", {
      className: "Marquee-noPhoto"
    }), m("b", null, c.name), m("span", null, c.role)))));
  }

  /** A show's seasons, once their chunk has loaded. */
  seasonBrowser(pick) {
    const SeasonBrowser = loadedSeasonBrowser();
    const {
      season,
      episode
    } = this.attrs.link;
    return SeasonBrowser ? m(SeasonBrowser, {
      link: pick,
      season: season,
      episode: episode
    }) : null;
  }
}
flarum.reg.add('ernestdefoe-marquee', 'forum/components/MediaHero', MediaHero);