import Model from 'flarum/common/Model';
/** A linked movie, show or game. `details` is only sent on the discussion page. */
export default class Media extends Model {
  kind() {
    return Model.attribute('kind').call(this);
  }
  externalId() {
    return Model.attribute('externalId').call(this);
  }
  title() {
    return Model.attribute('title').call(this);
  }
  year() {
    return Model.attribute('year').call(this);
  }
  poster() {
    return Model.attribute('poster').call(this);
  }
  artist() {
    return Model.attribute('artist').call(this);
  }
  details() {
    return Model.attribute('details').call(this);
  }
}