import app from 'flarum/forum/app';
const url = path => `${app.forum.attribute('apiUrl')}/marquee/${path}`;
// Callers handle a failure themselves (an empty list, a retry), so core's alert would only add noise.
const quiet = () => {};
export const search = (kind, q) => app.request({
  method: 'GET',
  url: url('search'),
  params: {
    kind,
    q
  },
  errorHandler: quiet
}).then(r => r.data);
export const lookup = (kind, id) => app.request({
  method: 'POST',
  url: url('media'),
  body: {
    kind,
    id
  },
  errorHandler: quiet
}).then(r => r.data);

/** A stored title's id. Models and picks type it as optional; a title with seasons always has one. */

const seasons = new Map();

/** One season with its episodes, fetched at most once per page load. */
export const loadSeason = (mediaId, number) => {
  const key = `${mediaId}:${number}`;
  let season = seasons.get(key);
  if (!season) {
    season = app.request({
      method: 'GET',
      url: url(`media/${mediaId}/seasons/${number}`),
      errorHandler: quiet
    }).then(r => r.data, e => {
      seasons.delete(key);
      throw e;
    });
    seasons.set(key, season);
  }
  return season;
};

/** A season that arrived with the discussion needs no request. */
export const primeSeason = (mediaId, data) => {
  if (data) seasons.set(`${mediaId}:${data.number}`, Promise.resolve(data));
};