import classList from 'flarum/common/utils/classList';
import abbreviateNumber from 'flarum/common/utils/abbreviateNumber';
import { t, text, img, date, runtime, igdbTerms, showScores, gameBackdrop } from './util';

/** What the card shows: the whole title, one season, or one episode. */

// The admin can hide every score and rating (on by default).
const ring = (value, label, kind) => value && showScores() ? m("div", {
  className: classList('MarqueeHero-score', kind && `MarqueeHero-score--${kind}`)
}, m("span", {
  className: "MarqueeHero-ring",
  style: {
    '--v': value
  }
}, m("b", null, value)), m("span", {
  className: "MarqueeHero-scoreLabel"
}, label)) : null;

/**
 * A screenshot stands in when IGDB has no wide artwork, unless the admin chose
 * artwork only, or no image at all. Titles stored before 1.16 have no
 * backdropShot: their screenshot backdrop was the first one shown.
 */
const gameBackdropOf = d => {
  const mode = gameBackdrop();
  if (mode === 'none') return null;
  const shot = d.backdropShot ?? (d.screenshots || []).includes(d.backdrop || '');
  return mode === 'artwork' && shot ? null : img(d.backdrop, 'w1280');
};
const credits = pairs => pairs.filter(([, names]) => names && names.length).map(([label, names]) => [label, [].concat(names || []).join(', ')]);
const years = d => {
  if (d.endYear && d.endYear !== d.year) return `${d.year}–${d.endYear}`;
  return d.status === 'Returning Series' ? `${d.year}–` : d.year;
};
const timeToBeat = ttb => ttb ? m("div", {
  className: "MarqueeHero-ttb"
}, m("h2", {
  className: "MarqueeHero-sectionTitle"
}, t('hero.time_to_beat')), m("dl", null, ['hastily', 'normally', 'completely'].filter(key => ttb[key]).map(key => m("div", null, m("dt", null, t(`hero.ttb_${key}`)), m("dd", null, t('hero.hours', {
  count: ttb[key]
})))))) : null;
const screenshots = list => list && list.length ? m("div", null, m("h2", {
  className: "MarqueeHero-sectionTitle"
}, t('hero.screenshots')), m("ul", {
  className: "MarqueeHero-shots"
}, list.map(shot => m("li", null, m("a", {
  href: img(shot, 'w1280'),
  target: "_blank",
  rel: "noopener noreferrer"
}, m("img", {
  src: img(shot, 'w300'),
  alt: "",
  loading: "lazy",
  decoding: "async"
})))))) : null;
const clock = seconds => `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
const tracklist = tracks => tracks && tracks.length ? m("div", null, m("h2", {
  className: "MarqueeHero-sectionTitle"
}, t('hero.tracklist')), m("ol", {
  className: "MarqueeTracks"
}, tracks.map(track => m("li", null, m("em", null, track.n), m("span", {
  className: "MarqueeTracks-title"
}, track.title, track.artist ? m("small", null, " \xB7 ", track.artist) : null), track.explicit ? m("abbr", {
  className: "MarqueeTracks-explicit",
  title: text('hero.explicit')
}, "E") : null, m("time", null, clock(track.duration)))))) : null;

/** One episode of a show. */
const episodeSubject = (d, season, episode, ep, seasonData, summary) => ({
  poster: seasonData.poster || summary?.poster || d.poster,
  backdrop: ep.still ? img(ep.still, 'w1280') : img(d.backdrop, 'w1280'),
  meta: [t('meta.season_episode', {
    season,
    episode
  }), date(ep.date), runtime(ep.runtime)],
  score: ring(ep.score, t('hero.episode_score')),
  credits: credits([[t('credits.directed_by'), ep.directors], [t('credits.written_by'), ep.writers], [t('credits.network'), d.networks]]),
  overview: ep.overview,
  people: [t('hero.guest_stars'), ep.guests],
  url: `${seasonData.url}/episode/${ep.n}`
});

/** One season of a show. */
const seasonSubject = (d, season, summary, seasonData) => ({
  poster: seasonData?.poster || summary.poster || d.poster,
  backdrop: img(d.backdrop, 'w1280'),
  meta: [summary.name, summary.year, t('meta.episodes_count', {
    count: summary.episodes
  }), d.genres.join(', ')],
  score: ring(summary.score, t('hero.season_score')),
  credits: credits([[t('credits.creator'), d.crew.creator], [t('credits.network'), d.networks]]),
  overview: seasonData?.overview || d.overview,
  people: [t('hero.cast'), d.cast],
  url: `${d.url}/season/${season}`
});

/** The whole title, one builder per kind; anything else is a movie. */
const titleSubjects = {
  tv: d => ({
    poster: d.poster,
    backdrop: img(d.backdrop, 'w1280'),
    meta: [years(d), d.certification, d.networks.join(', '), t('meta.seasons_count', {
      count: (d.seasons || []).length
    }), d.genres.join(', ')],
    score: [ring(d.score, t('hero.user_score')), d.tagline && m("p", {
      className: "MarqueeHero-tagline"
    }, d.tagline)],
    credits: credits([[t('credits.creator'), d.crew.creator], [t('credits.network'), d.networks], [t('credits.status'), d.status]]),
    overview: d.overview,
    people: [t('hero.cast'), d.cast],
    url: d.url
  }),
  music: d => ({
    poster: d.poster,
    backdrop: img(d.backdrop || d.poster, 'w1280'),
    meta: [date(d.date), t(`meta.record_${d.recordType}`), t('meta.tracks_count', {
      count: d.trackCount
    }), runtime(Math.round(d.duration / 60)), d.genres.join(', ')],
    score: d.fans ? m("p", {
      className: "MarqueeHero-fans"
    }, m("i", {
      className: "fas fa-heart",
      "aria-hidden": "true"
    }), " ", t('hero.fans', {
      count: abbreviateNumber(d.fans)
    })) : null,
    credits: credits([[t('credits.artist'), d.artist], [t('credits.label'), d.label]]),
    overview: null,
    extra: [tracklist(d.tracks)],
    url: d.url,
    linkLabel: t('hero.listen_on', {
      source: 'Deezer'
    })
  }),
  book: d => ({
    poster: d.poster,
    backdrop: img(d.poster, 'w1280'),
    meta: [d.year ? t('meta.first_published', {
      year: d.year
    }) : null, d.pages ? t('meta.pages_count', {
      count: d.pages
    }) : null, d.editions > 1 ? t('meta.editions_count', {
      count: d.editions
    }) : null],
    score: [d.subtitle && m("p", {
      className: "MarqueeHero-tagline"
    }, d.subtitle), d.rating && showScores() ? m("p", {
      className: "MarqueeHero-fans"
    }, m("i", {
      className: "fas fa-star",
      "aria-hidden": "true"
    }), " ", t('hero.book_rating', {
      rating: d.rating,
      count: abbreviateNumber(d.ratingCount)
    })) : null, d.readers ? m("p", {
      className: "MarqueeHero-fans"
    }, m("i", {
      className: "fas fa-bookmark",
      "aria-hidden": "true"
    }), " ", t('hero.want_to_read', {
      count: abbreviateNumber(d.readers)
    })) : null, d.subjects.length ? m("ul", {
      className: "MarqueeHero-chips"
    }, d.subjects.map(subject => m("li", null, subject))) : null],
    credits: credits([[t('credits.author'), d.authors], [t('credits.original_title'), d.originalTitle], [t('credits.publisher'), [d.publisher, d.published].filter(Boolean).join(', ')], [t('credits.isbn'), d.isbn]]),
    overview: d.overview,
    untranslated: d.untranslated,
    people: [t('hero.authors'), d.people.some(p => p.photo) ? d.people : []],
    url: d.url
  }),
  game: d => ({
    poster: d.poster,
    backdrop: gameBackdropOf(d),
    meta: [date(d.date), igdbTerms('mode', d.modes, d.modeSlugs).join(', '), igdbTerms('genre', d.genres, d.genreSlugs).join(', ')],
    score: [ring(d.critic, t('hero.critic_rating'), 'critic'), ring(d.users, t('hero.member_rating'), 'users'),
    // What this version is (Expansion, Remake…) first, as in search results.
    d.type || d.platforms.length ? m("ul", {
      className: "MarqueeHero-chips"
    }, d.type ? m("li", {
      className: "MarqueeHero-type"
    }, t(`picker.type.${d.type}`)) : null, d.platforms.map(p => m("li", null, p))) : null],
    credits: credits([[t('credits.developer'), d.crew.developer], [t('credits.publisher'), d.crew.publisher], [t('credits.series'), d.crew.series]]),
    overview: d.overview,
    untranslated: d.untranslated,
    extra: [timeToBeat(d.timeToBeat), screenshots(d.screenshots)],
    url: d.url
  }),
  movie: d => ({
    poster: d.poster,
    backdrop: img(d.backdrop, 'w1280'),
    meta: [date(d.date), d.certification, runtime(d.runtime), d.genres.join(', ')],
    score: [ring(d.score, t('hero.user_score')), d.tagline && m("p", {
      className: "MarqueeHero-tagline"
    }, d.tagline)],
    credits: credits([[t('credits.director'), d.crew.director], [t('credits.writer'), d.crew.writer], [t('credits.based_on'), d.crew.basedOn]]),
    overview: d.overview,
    people: [t('hero.cast'), d.cast],
    url: d.url
  })
};

/** What the hero is about: the whole title, one season, or one episode. */

export function subject(media, d, season, episode, seasonData) {
  const summary = season ? (d.seasons || []).find(s => s.number === season) : undefined;
  const ep = episode && seasonData ? seasonData.episodes.find(e => e.n === episode) : undefined;
  if (ep && episode && seasonData) return episodeSubject(d, season, episode, ep, seasonData, summary);
  if (summary && season) return seasonSubject(d, season, summary, seasonData);
  return (titleSubjects[media.kind()] || titleSubjects.movie)(d);
}